function findLargest(array) {
  if (!Array.isArray(array)) throw new Error("Input must be an array");

  // Handle empty arrays gracefully
  if (array.length === 0) return null;

  let largest = array[0];

  for (let i = 1; i < array.length; i++) {
    const number = array[i];
    // Use Number() to safely compare with mixed types, though strictly speaking numbers should be comparable here.
    if (number > largest) {
      largest = number;
    }
  }

  return largest;
}

// Example usage:
const numbers = [50, 23, 88, 12, 45];
console.log(findLargest(numbers)); // Output: 88
